def merge_config(defaults: dict, overrides: dict) -> dict:
    """Recursively merge overrides into defaults without mutating inputs.

    Nested dicts should be merged recursively.
    Non-dict override values replace the default value entirely.
    """
    result = dict(defaults)
    for key, override_value in overrides.items():
        default_value = result.get(key)
        if isinstance(default_value, dict) and isinstance(override_value, dict):
            result[key] = merge_config(default_value, override_value)
        else:
            result[key] = override_value
    return result

def normalize_identifier(raw: str) -> str:
    """Return a lowercase snake_case identifier built from a human label.

    Rules:
    - Trim leading/trailing whitespace.
    - Convert internal runs of whitespace or hyphens to a single underscore.
    - Remove any characters that are not ASCII letters, digits, underscores, spaces, or hyphens.
    - Collapse repeated underscores.
    """
    cleaned = []
    for char in raw.strip().lower():
        if char.isascii() and (char.isalnum() or char in {"_", " ", "-"}):
            cleaned.append(char)

    text = "".join(cleaned).replace("-", "_").replace(" ", "_")
    while "__" in text:
        text = text.replace("__", "_")
    return text.strip("_")

